import { add_remove_member_cabinet } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    leaveCabinetDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async leave_cabinet() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_remove_member_cabinet, {
          input: {
            folder_id: this.rowInfo.folder_id,
            user_id: [data.user.user_id],
            action_type: "LEAVE"
          }
        }));
        var response = JSON.parse(result.data.add_remove_member_cabinet);
        this.loading = false;
        if (response.Status === "SUCCESS") {
          this.$emit("successMsg", "You have successfully left the cabinet!");
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
